using VMLAssembler;

namespace VMLTranslators
{
    /// <summary>
    /// Motorola 68000 转译器 (16/32 位混合架构)
    /// </summary>
    public class Translator68000 : Translator32bit
    {
        public override string ARCH_NAME => "68000";

        // 68000 中断上下文
        private static readonly string[] M68kCtx = { "%d0","%d1","%d2","%d3","%d4","%d5","%d6","%d7","%a0","%a1","%a2","%a3","%a4","%a5","%a6" };
        protected override string[] ContextRegNames() => M68kCtx;
        protected override string NativeInt(int vector) => $"trap #{vector}";
        protected override string NativeIret() => "rte";
        protected override string NativeCli() => "andi.w #0xF8FF, %sr";
        protected override string NativeSti() => "ori.w #0x0700, %sr";
        protected override void EmitSaveContext() => Emit("        movem.l %d0-%d7/%a0-%a6,-(%sp)");
        protected override void EmitRestoreContext() => Emit("        movem.l (%sp)+,%d0-%d7/%a0-%a6");

        // 68000 寄存器映射
        // 数据寄存器: D0-D7 (32位)
        // 地址寄存器: A0-A7 (32位)，其中A7是栈指针
        // m68k GAS 寄存器命名：%dN 数据寄存器, %aN 地址寄存器, %sp 栈指针
        private readonly Dictionary<int, string> REGISTER_MAP = new Dictionary<int, string>
        {
            { 0, "%d0" },   // 数据寄存器0
            { 1, "%d1" },   // 数据寄存器1
            { 2, "%d2" },   // 数据寄存器2
            { 3, "%d3" },   // 数据寄存器3
            { 4, "%d4" },   // 数据寄存器4
            { 5, "%d5" },   // 数据寄存器5
            { 6, "%d6" },   // 数据寄存器6
            { 7, "%d7" },   // 数据寄存器7
            { 8, "%a0" },   // 地址寄存器0
            { 9, "%a1" },   // 地址寄存器1
            { 10, "%a2" },  // 地址寄存器2
            { 11, "%a3" },  // 地址寄存器3
            { 12, "%a4" },  // 地址寄存器4
            { 13, "%a5" },  // 地址寄存器5
            { 14, "%a6" },  // 地址寄存器6
            { 15, "%a7" }   // 地址寄存器7 (栈指针)
        };

        public Translator68000(VmlProgram vmlProgram) : base(vmlProgram) { }

        protected override void EmitHeader()
        {
            Emit("; Motorola 68000 Assembly - Translated from VML");
            Emit("; Generated by VML Translator");
            Emit("");
            Emit("        .cpu    68000");
            Emit("        .org    0x1000");
            Emit("");
        }

        protected override void EmitDataSection()
        {
            if (VmlProgram.DataSection.Count > 0)
            {
                Emit("");
                Emit("        .data");
                foreach (var kvp in VmlProgram.DataSection)
                {
                    string name = kvp.Key;
                    object value = kvp.Value;

                    if (value is string strValue)
                    {
                        var bytes = strValue.Select(c =>
                        {
                            if (c == '\n') return "0x0A";
                            if (c == '\r') return "0x0D";
                            if (c == '\t') return "0x09";
                            if (c == '\'') return "0x27";
                            if (c == '\\') return "0x5C";
                            if (c < 32 || c > 126) return $"0x{(byte)c:X2}";
                            return $"'{c}'";
                        });
                        Emit($"{name}:");
                        Emit($"        .dc.b    {string.Join(",", bytes)},0");
                    }
                    else if (value is System.Collections.IList listValue)
                    {
                        string vals = string.Join(", ", listValue);
                        Emit($"{name}: .dc.b    {vals}");
                    }
                    else if (int.TryParse(value.ToString(), out int intValue))
                    {
                        Emit($"{name}: .dc.l    {intValue}");
                    }
                }
            }
        }

        protected override void EmitCode()
        {
            Emit("");
            Emit("        .text");
            base.EmitCode();
        }

        protected override void TranslateInstruction(Instruction instr)
        {
            // NormalizeBinaryOp handled by BaseTranslator.NormalizeAndTranslate
            switch (instr.Opcode)
            {
                                                case OpCode.ADD:
                    TranslateAdd(instr);
                    break;
                case OpCode.SUB:
                    TranslateSub(instr);
                    break;
                case OpCode.MUL:
                    TranslateMul(instr);
                    break;
                case OpCode.DIV:
                    TranslateDiv(instr);
                    break;
                case OpCode.AND:
                    TranslateAnd(instr);
                    break;
                case OpCode.OR:
                    TranslateOr(instr);
                    break;
                case OpCode.XOR:
                    TranslateXor(instr);
                    break;
                case OpCode.NOT:
                    TranslateNot(instr);
                    break;
                case OpCode.SHL:
                    TranslateShl(instr);
                    break;
                case OpCode.SHR:
                    TranslateShr(instr);
                    break;
                case OpCode.CMP:
                    TranslateCmp(instr);
                    break;
                case OpCode.JMP:
                    TranslateJmp(instr);
                    break;
                case OpCode.JE:
                    TranslateJe(instr);
                    break;
                case OpCode.JNE:
                    TranslateJne(instr);
                    break;
                case OpCode.JG:
                    TranslateJg(instr);
                    break;
                case OpCode.JL:
                    TranslateJl(instr);
                    break;
                case OpCode.JGE:
                    TranslateJge(instr);
                    break;
                case OpCode.JLE:
                    TranslateJle(instr);
                    break;
                case OpCode.CALL:
                    TranslateCall(instr);
                    break;
                case OpCode.RET:
                    TranslateRet(instr);
                    break;
                case OpCode.PUSH:
                    TranslatePush(instr);
                    break;
                case OpCode.POP:
                    TranslatePop(instr);
                    break;
                case OpCode.MOVE:
                    TranslateMove(instr);
                    break;
                case OpCode.MOD:
                    Emit($"        DIVS.L   {GetOperandValue(instr.Operands[1])},{MapRegister(SafeToInt(instr.Operands[0].Value))}");
                    Emit($"        SWAP     {MapRegister(SafeToInt(instr.Operands[0].Value))}");
                    break;
                case OpCode.INC:
                    Emit($"        ADDQ.L   #1,{MapRegister(SafeToInt(instr.Operands[0].Value))}");
                    break;
                case OpCode.DEC:
                    Emit($"        SUBQ.L   #1,{MapRegister(SafeToInt(instr.Operands[0].Value))}");
                    break;
                case OpCode.NEG:
                    Emit($"        NEG.L    {MapRegister(SafeToInt(instr.Operands[0].Value))}");
                    break;
                case OpCode.JZ:
                    Emit($"        TST.L    {MapRegister(0)}");
                    Emit($"        BEQ      {GetOperandValue(instr.Operands[0])}");
                    break;
                case OpCode.JNZ:
                    Emit($"        TST.L    {MapRegister(0)}");
                    Emit($"        BNE      {GetOperandValue(instr.Operands[0])}");
                    break;
                case OpCode.TEST:
                    Emit($"        TST.L    {GetOperandValue(instr.Operands[0])}");
                    break;
                case OpCode.STI:
                // CLI/STI/INT/IRET handled by BaseTranslator.TryTranslateCommonOpcode
                case OpCode.THROW:
                    Emit("        ; THROW - 68000 exception");
                    break;
                case OpCode.CATCH:
                    break;
                case OpCode.ENDCATCH:
                    break;
                case OpCode.ENTER:
                    Emit($"        LINK     {MapRegister(14)},{GetOperandValue(instr.Operands[0])}");
                    break;
                case OpCode.LEAVE:
                    Emit($"        UNLK     {MapRegister(14)}");
                    break;                                case OpCode.BREAK:
                    Emit("        ; BREAK");
                    break;
                                                                                case OpCode.MOVEB:
                    Emit($"        MOVE.B   {GetOperandValue(instr.Operands[1])},{MapRegister(SafeToInt(instr.Operands[0].Value))}");
                    break;
                case OpCode.MOVEH:
                    Emit($"        MOVE.W   {GetOperandValue(instr.Operands[1])},{MapRegister(SafeToInt(instr.Operands[0].Value))}");
                    break;
                case OpCode.PUSHB:
                    Emit($"        MOVE.B   {GetOperandValue(instr.Operands[0])},-(A7)");
                    break;
                case OpCode.PUSHH:
                    Emit($"        MOVE.W   {GetOperandValue(instr.Operands[0])},-(A7)");
                    break;
                case OpCode.POPB:
                    Emit($"        MOVE.B   (A7)+,{MapRegister(SafeToInt(instr.Operands[0].Value))}");
                    break;
                case OpCode.POPH:
                    Emit($"        MOVE.W   (A7)+,{MapRegister(SafeToInt(instr.Operands[0].Value))}");
                    break;
                case OpCode.SHLV:
                    Emit($"        LSL.L    {GetOperandValue(instr.Operands[2])},{MapRegister(SafeToInt(instr.Operands[0].Value))}");
                    break;
                case OpCode.SHRV:
                    Emit($"        LSR.L    {GetOperandValue(instr.Operands[2])},{MapRegister(SafeToInt(instr.Operands[0].Value))}");
                    break;
                case OpCode.ZERO:
                    Emit($"        CLR.L    {MapRegister(SafeToInt(instr.Operands[0].Value))}");
                    break;
                // OpCode.CHIPASM handled by BaseTranslator.TryTranslateCommonOpcode
                // OpCode.ASM handled by BaseTranslator.TryTranslateCommonOpcode
                case OpCode.LABEL:
                    break;
                // case OpCode.RET_VAL:
                //     Emit("        RTS");
                //     break;
                case OpCode.FADD:
                case OpCode.FSUB:
                case OpCode.FMUL:
                case OpCode.FDIV:
                case OpCode.FCMP:
                case OpCode.MOVEF:
                                case OpCode.NOP:
                    TranslateNop(instr);
                    break;
                case OpCode.HALT:
                    TranslateHalt(instr);
                    break;
                case OpCode.SYSCALL:
                    TranslateSyscall(instr);
                    break;
                // 符号扩展/条件移动/循环移位 (v1.66.28+) — 软件库
                case OpCode.SEXTB: case OpCode.SEXTH:
                case OpCode.CMOVZ: case OpCode.CMOVNZ:
                case OpCode.ROL: case OpCode.ROR:
                    Emit($"        jsr __{instr.Opcode.ToString().ToLower()}");
                    break;
                default:
                    Emit($"; Unknown instruction: {instr.Opcode}");
                    break;
            }
        }

        protected override string MapRegister(int regNum)
        {
            if (REGISTER_MAP.TryGetValue(regNum, out string regName))
            {
                return regName;
            }
            return $"R{regNum}";
        }

        private void TranslateLoad(Instruction instr)
        {
            if (instr.Operands.Count >= 2)
            {
                string dest = MapRegister(SafeToInt(instr.Operands[0].Value));
                string src = GetOperandValue(instr.Operands[1]);

                if (instr.Operands[1].Type == OperandType.IMMEDIATE)
                {
                    Emit($"        MOVE.L   {src},{dest}");
                }
                else if (instr.Operands[1].Type == OperandType.MEMORY)
                {
                    Emit($"        MOVE.L   {src},{dest}");
                }
                else if (instr.Operands[1].Type == OperandType.REGISTER)
                {
                    Emit($"        MOVE.L   {src},{dest}");
                }
                else if (instr.Operands[1].Type == OperandType.LABEL)
                {
                    // LEA requires address register, use MOVE.L for data regs
                    int dstNum = SafeToInt(instr.Operands[0].Value);
                    if (dstNum < 8)
                        Emit($"        MOVE.L   {src},{dest}");  // D0-D7: src=label name
                    else
                        Emit($"        LEA      {src},{dest}");   // A0-A6: use LEA
                }
            }
        }

        private void TranslateStore(Instruction instr)
        {
            if (instr.Operands.Count >= 2)
            {
                string dest = GetOperandValue(instr.Operands[0]);
                string src = GetOperandValue(instr.Operands[1]);

                Emit($"        MOVE.L   {src},{dest}");
            }
        }

