        private void TranslateRet(Instruction instr)
        {
            Emit("        RTS");
        }

        private void TranslatePush(Instruction instr)
        {
            if (instr.Operands.Count >= 1)
            {
                string src = GetOperandValue(instr.Operands[0]);
                Emit($"        MOVE.L   {src},-(A7)");
            }
        }

        private void TranslatePop(Instruction instr)
        {
            if (instr.Operands.Count >= 1)
            {
                string dest = GetOperandValue(instr.Operands[0]);
                Emit($"        MOVE.L   (A7)+,{dest}");
            }
        }

        private void TranslateMove(Instruction instr)
        {
            // v1.65.167+: 统一 MOVE — MEM/LABEL dest → Store, 其他 → Load
            if (instr.Operands[0].Type == OperandType.MEMORY ||
                instr.Operands[0].Type == OperandType.INDIRECT ||
                instr.Operands[0].Type == OperandType.LABEL)
            {
                TranslateStore(instr);
                return;
            }
            TranslateLoad(instr);
        }

        private void TranslateNop(Instruction instr)
        {
            Emit("        NOP");
        }

        private void TranslateHalt(Instruction instr)
        {
            Emit("        STOP    #$2700");
        }



        private void TranslateSyscall(Instruction instr)
        {
            if (instr.Operands.Count >= 1)
            {
                string syscallNum = instr.Operands[0].Value.ToString();
                Emit($"; SYSCALL {syscallNum}");
                if (syscallNum == "1")
                    Emit("        JSR     sys_write");
                else if (syscallNum == "3")
                {   Emit(".halt:"); Emit("        STOP    #0x2700"); Emit("        BRA     .halt"); }
                else if (syscallNum == "4")
                    Emit("        JSR     sys_putc");
                else
                    Emit($"        TRAP    #{syscallNum}");
            }
        }

        protected override string GetOperandValue(Operand operand)
        {
            switch (operand.Type)
            {
                case OperandType.IMMEDIATE:
                    return $"#{operand.Value}";
                case OperandType.REGISTER:
                    return MapRegister(SafeToInt(operand.Value));
                case OperandType.MEMORY:
                    // 68000内存寻址格式: (地址) 或 偏移(基址寄存器)
                    if (operand.Value is string strValue && strValue.StartsWith("["))
                    {
                        // 简单内存地址，如 [0x1000]
                        string addr = strValue.Trim('[', ']');
                        return $"({addr})";
                    }
                    return $"({operand.Value})";
                default:
                    return operand.Value.ToString();
            }
        }
